function Badge({ children, tone }: { children: ReactNode; tone?: Tone }) {
  const value = String(children).toLowerCase();
  const inferred: Tone = tone || (/(complete|approved|paid|online|captured|resolved)/.test(value) ? "green" : /(fail|cancel|reject|expired|suspend|overdue)/.test(value) ? "red" : /(search|pending|review|wait|held|soon|pickup)/.test(value) ? "amber" : "blue");
  return <span className={`admin-badge ${inferred}`}>{children}</span>;
}

function AdminButton({ children, onClick, tone = "primary", icon }: { children: ReactNode; onClick?: () => void; tone?: "primary"|"secondary"|"danger"|"ghost"; icon?: IconName }) {
  return <button className={`admin-button ${tone}`} onClick={onClick}>{icon && <Icon name={icon} size={16}/>}<span>{children}</span></button>;
}

function Sidebar({ page, go, close }: { page: Page; go:(p:Page)=>void; close:()=>void }) {
  return <aside className="admin-sidebar"><div className="admin-brand"><span className="brand-mark">P</span><div><strong>PORTER</strong><small>OPERATIONS</small></div><button onClick={close}><Icon name="x"/></button></div><nav>{nav.map(([key,icon,label,count])=><button key={key} className={page===key?"active":""} onClick={()=>go(key)}><Icon name={icon}/><span>{label}</span>{count&&<i>{count}</i>}</button>)}</nav><div className="sidebar-health"><span><i/> SYSTEMS OPERATIONAL</span><small>Last checked 30 sec ago</small></div><div className="sidebar-user"><span>AL</span><div><strong>Amelia Lewis</strong><small>Operations Admin</small></div><Icon name="chevron" size={16}/></div></aside>;
}

function Header({ title, subtitle, toggle, search, notify }: { title:string; subtitle:string; toggle:()=>void; search:()=>void; notify:()=>void }) {
  return <header className="admin-header"><button className="menu-toggle" onClick={toggle}><Icon name="briefcase"/></button><div><strong>{title}</strong><span>{subtitle}</span></div><button className="global-search" onClick={search}><Icon name="search"/><span>Search jobs, drivers, customers…</span><kbd>⌘ K</kbd></button><div className="header-actions"><button onClick={notify}><Icon name="message"/><i>5</i></button><span className="ops-live"><i/> LIVE</span><button className="admin-avatar">AL</button></div></header>;
}

function PageTitle({ eyebrow, title, children }: { eyebrow?:string; title:string; children?:ReactNode }) {
  return <div className="admin-page-title"><div>{eyebrow&&<span>{eyebrow}</span>}<strong>{title}</strong></div><div>{children}</div></div>;
}

function Metric({ label, value, change, icon, tone="blue" }: { label:string; value:string; change:string; icon:IconName; tone?:Tone }) {
  return <div className="admin-metric"><div className={`admin-metric-icon ${tone}`}><Icon name={icon}/></div><span>{label}</span><strong>{value}</strong><small className={change.startsWith("−")?"down":""}>{change}</small></div>;
}

function FilterBar({ type="jobs" }: { type?:string }) {
  return <div className="filter-bar"><button className="filter-search"><Icon name="search" size={17}/> Search {type}…</button><button><Icon name="document" size={15}/> Status <Icon name="chevron" size={14}/></button><button><Icon name="van" size={15}/> {type==="drivers"?"Vehicle":"Type"} <Icon name="chevron" size={14}/></button><button><Icon name="calendar" size={15}/> Date range <Icon name="chevron" size={14}/></button><button className="more-filter"><Icon name="plus" size={15}/> More filters</button><span>6 results</span></div>;
}

function DataTable({ columns, rows, onRow }: { columns:string[]; rows:string[][]; onRow?:(row:string[])=>void }) {
  return <div className="table-wrap"><table><thead><tr>{columns.map(c=><th key={c}>{c}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i} onClick={()=>onRow?.(r)}>{r.map((v,j)=><td key={j}>{["Status","Payment","Approval","Online","Documents"].includes(columns[j])?<Badge>{v}</Badge>:j===0?<strong>{v}</strong>:v}</td>)}</tr>)}</tbody></table><div className="responsive-cards">{rows.map((r,i)=><button key={i} onClick={()=>onRow?.(r)}>{columns.slice(0,6).map((c,j)=><span key={c}><small>{c}</small><strong>{["Status","Payment","Approval","Online","Documents"].includes(c)?<Badge>{r[j]}</Badge>:r[j]}</strong></span>)}<Icon name="chevron"/></button>)}</div></div>;
}

