function Modal({ type, close, confirm }: { type:string; close:()=>void; confirm:()=>void }) {
  const config:Record<string,[string,string,string]>={cancel:["Cancel this job?","The job will return to cancelled state and the customer may receive a refund.","Cancel job"],assign:["Assign a driver","Marcus Taylor is 2.4 km away and eligible for this Van delivery.","Assign Marcus"],reassign:["Reassign driver?","Marcus will be released and the job will return to the search pool.","Reassign job"],suspend:["Suspend this driver?","Marcus will immediately go Offline and cannot accept offers. A reason will be recorded.","Suspend driver"],unsuspend:["Restore driver access?","Marcus will be eligible to go Online again.","Unsuspend driver"],"reject-document":["Reject insurance document","A rejection reason is required and the driver will be asked to resubmit.","Reject document"],resolve:["Resolve with partial refund","Review the financial impact before confirming this dispute decision.","Confirm resolution"],refund:["Simulate a refund","No real money moves in this prototype. This demonstrates the safe refund workflow.","Confirm $20 refund"],publish:["Publish pricing v3.3?","New quotes use this version from the effective date. Existing job prices remain locked.","Publish pricing"],reset:["Reset all demo data?","This action restores every prototype state and cannot be undone.","Reset demo data"]};
  const c=config[type]||["Confirm action","Please review before continuing.","Confirm"];
  return <div className="modal-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&close()}><div className="confirmation-modal" role="dialog" aria-modal="true"><span className={/(cancel|suspend|reject|reset)/.test(type)?"danger":""}><Icon name={/(cancel|suspend|reject|reset)/.test(type)?"shield":"check"} size={25}/></span><strong>{c[0]}</strong><p>{c[1]}</p>{type==="resolve"&&<div className="modal-finance">{[["Customer paid","$54.80"],["Partial refund","− $20.00"],["Driver deduction","− $8.00"],["Remaining driver payout","$27.40"]].map(x=><div key={x[0]}><span>{x[0]}</span><b>{x[1]}</b></div>)}</div>}{/(suspend|reject|cancel)/.test(type)&&<label>REASON<textarea defaultValue={type==="suspend"?"Safety review required":""}/></label>}<div><AdminButton tone="ghost" onClick={close}>Go back</AdminButton><AdminButton tone={/(cancel|suspend|reject|reset)/.test(type)?"danger":"primary"} onClick={confirm}>{c[2]}</AdminButton></div></div></div>;
}

