export default function AdminApp() {
  const [page,setPage]=useState<Page>("overview"),[drawer,setDrawer]=useState(false),[command,setCommand]=useState(false),[notifications,setNotifications]=useState(false),[modal,setModal]=useState(""),[toast,setToast]=useState(""),[disputeResolved,setDisputeResolved]=useState(false),[driverSuspended,setDriverSuspended]=useState(false);
  const go=(p:Page)=>{setPage(p);setDrawer(false);window.scrollTo(0,0);};
  const showToast=(s:string)=>{setToast(s);window.setTimeout(()=>setToast(""),2600);};
  const confirm=()=>{const current=modal;setModal("");showToast(current==="resolve"?"Dispute resolved and refund queued":current==="assign"?"Marcus assigned to JOB-1047":current==="publish"?"Pricing v3.3 published successfully":"Action completed successfully");if(current==="resolve"){setDisputeResolved(true);setPage("dispute");}if(current==="suspend")setDriverSuspended(true);if(current==="unsuspend")setDriverSuspended(false);};
  let content:ReactNode;
  if(page==="overview")content=<Overview go={go} toast={showToast}/>;
  else if(page==="jobs")content=<Jobs go={go}/>;
  else if(page==="job")content=<JobDetail go={go} modal={setModal} toast={showToast}/>;
  else if(page==="map")content=<LiveMap go={go}/>;
  else if(page==="drivers")content=<Drivers go={go}/>;
  else if(page==="driver")content=<DriverDetail go={go} modal={setModal} toast={showToast} suspended={driverSuspended}/>;
  else if(page==="review")content=<ApplicationReview go={go} toast={showToast}/>;
  else if(page==="customers")content=<Customers go={go}/>;
  else if(page==="customer")content=<CustomerDetail go={go} toast={showToast}/>;
  else if(page==="disputes")content=<Disputes go={go}/>;
  else if(page==="dispute")content=<DisputeDetail go={go} modal={setModal} toast={showToast} resolved={disputeResolved}/>;
  else if(page==="pricing")content=<Pricing modal={setModal} toast={showToast}/>;
  else if(page==="payments")content=<Payments go={go}/>;
  else if(page==="payment")content=<PaymentDetail go={go} modal={setModal}/>;
  else if(page==="payouts")content=<Payouts/>;
  else if(page==="reports")content=<Reports/>;
  else if(page==="audit")content=<Audit/>;
  else content=<Settings modal={setModal} toast={showToast}/>;
  return <div className="admin-app"><div className={`sidebar-shell ${drawer?"open":""}`}><Sidebar page={page} go={go} close={()=>setDrawer(false)}/></div>{drawer&&<button className="drawer-scrim" onClick={()=>setDrawer(false)} aria-label="Close navigation"/>}<div className="admin-main"><Header title={titles[page][0]} subtitle={titles[page][1]} toggle={()=>setDrawer(true)} search={()=>setCommand(true)} notify={()=>setNotifications(true)}/><main className="admin-content">{content}</main></div>{modal&&<Modal type={modal} close={()=>setModal("")} confirm={confirm}/>} {command&&<Command close={()=>setCommand(false)} go={go}/>} {notifications&&<><button className="drawer-scrim alerts" onClick={()=>setNotifications(false)}/><Notifications close={()=>setNotifications(false)} go={go}/></>} {toast&&<div className="admin-toast"><Icon name="check"/><span>{toast}</span></div>}</div>;
}
